/** src/lib/logger.ts as 2.0.0 had it */
export declare const OLD_LOGGER = "import { dev } from '$app/env';\nimport pino from 'pino';\n\n// Create different logger configurations for server and browser\nconst createLogger = () => {\n\treturn pino({\n\t\tlevel: dev ? 'debug' : 'info',\n\t\tredact: [\n\t\t\t'password',\n\t\t\t'*.password',\n\t\t\t'cookie',\n\t\t\t'*.cookie',\n\t\t\t'authorization',\n\t\t\t'*.authorization',\n\t\t\t'req.headers.cookie',\n\t\t\t'req.headers.authorization'\n\t\t],\n\t\ttransport: dev\n\t\t\t? {\n\t\t\t\t\ttarget: 'pino-pretty',\n\t\t\t\t\toptions: {\n\t\t\t\t\t\tcolorize: true,\n\t\t\t\t\t\ttranslateTime: 'SYS:yyyy-mm-dd HH:MM:ss'\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t: undefined\n\t});\n};\n\nconst baseLogger = createLogger();\n\nexport const logger = Object.assign(baseLogger, {\n\tinspect: (...args: unknown[]) => {\n\t\tif (dev) {\n\t\t\tconsole.log(...args);\n\t\t}\n\t},\n\tdir: (obj: unknown, options?: Parameters<typeof console.dir>[1]) => {\n\t\tif (dev) {\n\t\t\tconsole.dir(obj, options);\n\t\t}\n\t},\n\ttable: (data: unknown, columns?: string[]) => {\n\t\tif (dev) {\n\t\t\tconsole.table(data, columns);\n\t\t}\n\t}\n});\n";
